for title, content in framework_details:
    add_heading(title, level=2)
    # split content into paragraphs ~800 chars
    parts = content.replace('\n',' ').split('. ')
    # Group into chunks of ~4 sentences
    chunk = ""
    for sentence in parts:
        chunk += sentence + ". "
        if len(chunk) > 700:
            add_para(chunk.strip())
            chunk = ""
    if chunk:
        add_para(chunk.strip())
    add_bullet("Exam technique drill: Attempt to write 10-mark answer on this framework using PEA-C with 2 scenario facts from MSL airline PRAN RMG telecom", bold_prefix="Drill: ")

